effect.shader:
const float PI = 3.14159265;
float rand(vec2 c){ return fract(sin(dot(c,vec2(12.9898,78.233)))*43758.5453); }
void main(){
    vec4 src=texture2DCv(inputImg.texture, acScreenNorm);
    vec2 p=acScreenNorm-0.5; float asp=acScreenSize.x/acScreenSize.y; p.x*=asp;
    float r=length(p)+0.001;
    float ang=atan(p.y,p.x);
    float id=floor(ang*24.0/(2.0*PI));
    float h=rand(vec2(id,1.0));
    float streak=fract(h*53.0 - acTime*speed*(0.5+h));
    float line=smoothstep(0.02,0.0,abs(fract(ang*24.0/(2.0*PI))-0.5));
    float bright=smoothstep(0.0,1.0,streak)*line*r*2.0;
    vec3 stars=color.rgb*bright;
    vec3 outc=1.0-(1.0-src.rgb)*(1.0-stars);
    gl_FragColor=mix(src, vec4(outc,1.0), amount);
}
